const stableGuestImportId=async(backup:GuestBackup)=>{const normalized={businessName:backup.businessName,currency:backup.currency,documentSettings:backup.documentSettings??null,clients:[...backup.clients].map(c=>({id:c.id,name:c.name,email:c.email,company:c.company})).sort((a,b)=>a.id.localeCompare(b.id)),invoices:[...backup.invoices].map(i=>({id:i.id,clientId:i.clientId??null,customerName:i.customerName??null,customerEmail:i.customerEmail??"",customerCompany:i.customerCompany??"",issueDate:i.issueDate,dueDate:i.dueDate,paidAt:i.paidAt??null,description:i.description,quantity:i.quantity,unitPriceMinor:i.unitPriceMinor,lineItems:i.lineItems??[],documentDesign:i.documentDesign??null,currency:i.currency,status:i.status})).sort((a,b)=>a.id.localeCompare(b.id)),quotes:[...(backup.quotes??[])].map(q=>({id:q.id,customerName:q.customerName,customerEmail:q.customerEmail,customerCompany:q.customerCompany,description:q.description,issueDate:q.issueDate,validUntil:q.validUntil,quantity:q.quantity,unitPriceMinor:q.unitPriceMinor,lineItems:q.lineItems??[],documentDesign:q.documentDesign??null,currency:q.currency,status:q.status})).sort((a,b)=>a.id.localeCompare(b.id)),expenses:[...backup.expenses].map(e=>({id:e.id??"",vendor:e.vendor,category:e.category,date:e.date,amountMinor:e.amountMinor,currency:e.currency})).sort((a,b)=>JSON.stringify(a).localeCompare(JSON.stringify(b)))};const digest=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(JSON.stringify(normalized)));const bytes=Array.from(new Uint8Array(digest).slice(0,16));bytes[6]=((bytes[6]??0)&15)|80;bytes[8]=((bytes[8]??0)&63)|128;const hex=bytes.map(b=>b.toString(16).padStart(2,"0")).join("");return `${hex.slice(0,8)}-${hex.slice(8,12)}-${hex.slice(12,16)}-${hex.slice(16,20)}-${hex.slice(20)}`};
