 const [store,setStore]=useState<Store>(seed),[loaded,setLoaded]=useState(false),[loadError,setLoadError]=useState("");
 const [actionError,setActionError]=useState(""),[saving,setSaving]=useState(false);
 const [pdfTarget,setPdfTarget]=useState<{input:DocumentPdfInput;fileName:string}|null>(null),[pdfTemplate,setPdfTemplate]=useState<DocumentTemplateId>("modern"),[pdfPreviewUrl,setPdfPreviewUrl]=useState("");
 const [active,setActive]=useState("Overview"),[query,setQuery]=useState(""),[create,setCreate]=useState(""),[createInitialData,setCreateInitialData]=useState<CreateDocumentPrefill|null>(null),[notice,setNotice]=useState(false),[mobileMoreOpen,setMobileMoreOpen]=useState(false),[mobileSearchOpen,setMobileSearchOpen]=useState(false),[delayLateInvoices,setDelayLateInvoices]=useState(false),[cashflowDelayDays,setCashflowDelayDays]=useState("14"),[openingCashInput,setOpeningCashInput]=useState(""),[reserveCashInput,setReserveCashInput]=useState("0");
