 useEffect(()=>{if(!create)setCreateInitialData(null)},[create]);
 useEffect(()=>{const handleShortcut=(event:KeyboardEvent)=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==="k"){event.preventDefault();if(window.matchMedia("(max-width:560px)").matches)setMobileSearchOpen(true);else document.querySelector<HTMLInputElement>(".search-box input")?.focus()}};window.addEventListener("keydown",handleShortcut);return()=>window.removeEventListener("keydown",handleShortcut)},[]);
 useEffect(()=>{if(!pdfTarget){setPdfPreviewUrl("");return;}const url=URL.createObjectURL(createDocumentPdf({...pdfTarget.input,template:pdfTemplate}));setPdfPreviewUrl(url);return()=>URL.revokeObjectURL(url)},[pdfTarget,pdfTemplate]);
 useEffect(()=>{setOpeningCashInput(store.openingCashBalanceMinor===null?"":minorToDecimalInput(store.openingCashBalanceMinor,store.currency));setReserveCashInput(minorToDecimalInput(store.cashReserveMinor,store.currency))},[store.openingCashBalanceMinor,store.cashReserveMinor,store.currency]);
 useEffect(()=>{let alive=true;(async()=>{try{const response=await fetch("/api/workspace",{cache:"no-store"});const result=await response.json() as {error?:string;workspace:Store};if(!response.ok)throw new Error(result.error||"Workspace could not be loaded.");if(alive){setStore(result.workspace);setLoaded(true)}}catch(error){if(alive){setLoadError(error instanceof Error?error.message:"Workspace could not be loaded.");setLoaded(true)}}})();return()=>{alive=false}},[]);
 useEffect(()=>{try{const pending=localStorage.getItem(GUEST_PENDING_IMPORT_KEY);const local=localStorage.getItem(GUEST_STORAGE_KEY);const raw=pending??local;if(!raw)return;const parsed=JSON.parse(raw) as GuestBackup;if(parsed&&Array.isArray(parsed.clients)&&Array.isArray(parsed.invoices)&&Array.isArray(parsed.expenses)){setGuestBackup(parsed);setGuestBackupSource(pending?"file":"local")}else setGuestBackupError("A guest backup was found, but its format could not be recognised. Export it from Guest mode before importing.")}catch{setGuestBackupError("We could not read the guest backup saved in this browser. Your cloud workspace has not been changed.")}},[]);
 const mutate=async(payload:Record<string,unknown>)=>{setSaving(true);setActionError("");try{const response=await fetch("/api/workspace",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});const result=await response.json() as {error?:string;workspace:Store};if(!response.ok)throw new Error(result.error||"The change could not be saved.");setStore(result.workspace);return true}catch(error){setActionError(error instanceof Error?error.message:"The change could not be saved.");return false}finally{setSaving(false)}};
 const searchTerm=query.trim().toLowerCase();
 const filteredInvoices=useMemo(()=>store.invoices.filter(i=>{const c=store.clients.find(x=>x.id===i.clientId);return [i.number,i.customerName,c?.name,i.description,i.status,i.dueDate].join(" ").toLowerCase().includes(searchTerm)}),[store,searchTerm]);
 const filteredQuotes=useMemo(()=>store.quotes.filter(q=>[q.number,q.customerName,q.description,q.status].join(" ").toLowerCase().includes(searchTerm)),[store,searchTerm]);
