 const filteredPayments=useMemo(()=>store.payments.filter(p=>{const invoice=store.invoices.find(i=>i.id===p.invoiceId);const client=store.clients.find(c=>c.id===p.clientId);return [p.reference,p.notes,p.method,p.date,invoice?.number,invoice?.customerName,client?.name].join(" ").toLowerCase().includes(searchTerm)}),[store,searchTerm]);
 const filteredExpenses=useMemo(()=>store.expenses.filter(e=>[e.vendor,e.category,e.date,e.notes].join(" ").toLowerCase().includes(searchTerm)),[store,searchTerm]);
 const invoiced=invoiceTotal(store.invoices.filter(i=>i.status!=="Draft"&&i.currency===store.currency));
 const collected=moneyTotal(store.payments.filter(p=>p.currency===store.currency));
 const balanceFor=(invoice:Invoice)=>outstandingBalanceMinor(invoiceAmountMinor(invoice),store.payments.filter(p=>p.invoiceId===invoice.id).map(p=>p.amountMinor));
 const awaiting=store.invoices.filter(i=>(i.status==="Sent"||i.status==="Partially paid")&&i.currency===store.currency).reduce((sum,i)=>sum+balanceFor(i),0);
 const overdue=store.invoices.filter(i=>i.status==="Overdue"&&i.currency===store.currency).reduce((sum,i)=>sum+balanceFor(i),0);
 const clientPaymentProfiles=useMemo(()=>buildClientPaymentProfiles({asOfDate:today(),clients:store.clients.map(c=>({id:c.id,name:c.name,currency:c.currency})),invoices:store.invoices.map(i=>({id:i.id,clientId:i.clientId,issueDate:i.issueDate,dueDate:i.dueDate,quantity:i.quantity,unitPriceMinor:i.unitPriceMinor,lineItems:i.lineItems,currency:i.currency,status:i.status})),payments:store.payments.map(p=>({invoiceId:p.invoiceId,date:p.date,amountMinor:p.amountMinor,currency:p.currency,method:p.method}))}),[store.clients,store.invoices,store.payments]);
 const clientPaymentProfileById=useMemo(()=>new Map(clientPaymentProfiles.map(profile=>[profile.clientId,profile])),[clientPaymentProfiles]);
 const cashflowInput=useMemo(()=>({asOfDate:today(),currency:store.currency,openingBalanceMinor:store.openingCashBalanceMinor,reserveMinor:store.cashReserveMinor,invoices:store.invoices.filter(i=>i.currency===store.currency).map(i=>cashflowInvoiceFromDocument({id:i.id,number:i.number,customerName:i.customerName??store.clients.find(c=>c.id===i.clientId)?.name??"Customer",dueDate:i.dueDate,description:i.description,quantity:i.quantity,unitPriceMinor:i.unitPriceMinor,lineItems:i.lineItems,status:i.status,currency:i.currency,paidMinor:store.payments.filter(p=>p.invoiceId===i.id&&p.currency===i.currency).reduce((sum,p)=>sum+p.amountMinor,0)})),outflows:store.expenses.filter(e=>e.currency===store.currency).map(e=>({id:e.id,label:e.vendor+" · "+e.category,date:e.date,amountMinor:e.amountMinor,currency:e.currency}))}),[store.currency,store.openingCashBalanceMinor,store.cashReserveMinor,store.invoices,store.payments,store.expenses,store.clients]);
 const cashflowBaseline=useMemo(()=>{try{return {forecast:calculateCashflow(cashflowInput),error:""}}catch(error){return {forecast:null,error:error instanceof Error?error.message:"Cash-flow forecast could not be calculated."}}},[cashflowInput]);
