 const editQuote=(quote:Quote)=>{if(quote.status!=="Draft"){setActionError("Only draft quotations can be edited.");return;}setCreateInitialData({id:quote.id,customerName:quote.customerName,customerEmail:quote.customerEmail,customerCompany:quote.customerCompany,description:quote.description,quantity:quote.quantity,unitPriceMinor:quote.unitPriceMinor,lineItems:quote.lineItems,currency:quote.currency,validUntil:quote.validUntil});setCreate("Quote")};
